{
  "name": "@kinski/opencode-web-gateway",
  "version": "1.0.1",
  "description": "Global CLI and opencode plugin: browser-egress WebSocket bridge for the native DeepSeek provider.",
  "type": "module",
  "main": "./dist/index.js",
  "bin": {
    "opencode-web-gateway": "bin/opencode-web-gateway.js"
  },
  "exports": {
    ".": "./dist/index.js"
  },
  "files": [
    "bin",
    "dist",
    "examples",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "prepack": "node ../scripts/prepare-packages.mjs"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "deepseek",
    "websocket",
    "bridge",
    "browser",
    "llm"
  ],
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "engines": {
    "node": ">=20"
  }
}
